use anyhow::Result;use liquid_sense::{model::{Model,Session},chat::{Chat,Message,render}};use std::{path::Path,sync::atomic::AtomicBool};
fn main()->Result<()>{rayon::ThreadPoolBuilder::new().num_threads(4).build_global()?;let args:Vec<_>=std::env::args().collect();let model=Model::open(Path::new(&args[1]))?;let cancel=AtomicBool::new(false);
 if args[2]=="trace" {let fixture:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[3])?)?;let mut session=Session::new();let mut steps=vec![];for step in fixture["steps"].as_array().unwrap(){let id=step["input_id"].as_u64().unwrap() as u32;let(h,states)=model.token(&mut session,id,&cancel,true)?;let logits=model.logits(&h);let mut top:Vec<_>=logits.iter().copied().enumerate().collect();top.sort_unstable_by(|a,b|b.1.total_cmp(&a.1));let selected:Vec<f32>=step["top_ids"].as_array().unwrap().iter().map(|v|logits[v.as_u64().unwrap() as usize]).collect();steps.push(serde_json::json!({"input_id":id,"states":states,"argmax":top[0].0,"reference_top_logits":selected}));}println!("{}",serde_json::json!({"quantization":model.manifest.quantization,"steps":steps}));}
 else {let dir=Path::new(&args[1]).parent().unwrap();let tokenizer=tokenizers::Tokenizer::from_file(dir.join("tokenizer.json")).map_err(|e|anyhow::anyhow!(e.to_string()))?;let identity:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("identity.json"))?)?;let chat=Chat{model,tokenizer,system:identity["system_message"].as_str().unwrap().to_string()};if args[2]=="tokenizer"{let v:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("tokenizer_fixture.json"))?)?;let messages:Vec<Message>=serde_json::from_value(v["messages"].clone())?;let rendered=render(&chat.system,&messages[1..]);let ids=chat.tokenizer.encode(rendered.clone(),false).map_err(|e|anyhow::anyhow!(e.to_string()))?.get_ids().to_vec();println!("{}",serde_json::json!({"rendered":rendered,"ids":ids}));}else{let messages=vec![Message{role:"user".into(),content:args[3].clone()}];let answer=chat.generate(&messages,if args.len()>4{args[4].parse()?}else{64},&cancel,|_,_,_|{})?;println!("{}",serde_json::to_string(&answer)?);}}
 Ok(())}
